// Organiza somente os campos necessarios para os proximos nodes.
// O payload Meta e o contrato interno atual nao informam se o contato e novo.
// Por isso este node nao inventa uma flag de primeira mensagem.
const evento = $('When Executed by Another Workflow').first().json.evento ?? {};
const dentroHorario = typeof evento.dentro_horario_humano === 'boolean' ? evento.dentro_horario_humano : null;

return [{ json: {
  mensagem_cliente: String(evento.texto ?? '').trim(),
  contato: { wa_id: String(evento.wa_id ?? '').trim(), nome: String(evento.nome_contato ?? '').trim() },
  metadados: {
    mensagem_id: String(evento.mensagem_id ?? ''),
    phone_number_id: String(evento.phone_number_id ?? ''),
    atendimento_id: String(evento.atendimento_id ?? ''),
    lead_id: String(evento.lead_id ?? ''),
    recebido_em: evento.recebido_em ?? null
  },
  transferencia_lista_resposta: evento.transferencia_lista_resposta ?? null,
  crm_entrada: {
    atendimento_modo: String(evento.atendimento_modo ?? ''),
    ia_ativa: typeof evento.ia_ativa === 'boolean' ? evento.ia_ativa : null
  },
  horario: { dentro_horario_humano: dentroHorario, origem: dentroHorario === null ? 'NAO_INFORMADO' : 'HEADER_CRM' }
} }];

// Junta o contexto do CRM com dados minimos para a IA decidir a triagem.
// Para transferencia, todos os usuarios ativos com papel ATENDENTE sao elegiveis, mesmo offline.
const preparado = $('Busca atendimento id').first().json;
if (preparado.crm?.ia_autorizada !== true) {
  throw new Error('ATENDIMENTO_NAO_AUTORIZADO_PARA_IA');
}
const disponiveisBrutos = $('Consultar atendentes disponiveis').all().map((item) => item.json);
const usuarios = $('Compactar equipe CRM').first().json.usuarios ?? [];
const configBruta = $('Buscar configuracao automacao').first().json ?? {};
const faqBruta = $('Consultar FAQ institucional no Postgres').first().json ?? {};
const variaveis = $('Variaveis de producao').first().json;
const timezone = String(variaveis.timezone ?? '').trim();
if (!timezone) throw new Error('TIMEZONE_NAO_CONFIGURADO');
const textoFaqInstitucionalVazia = String(variaveis.faq_institucional_vazia ?? '').trim();
const textoFaqHorarioVazio = String(variaveis.faq_horario_vazio ?? '').trim();
const textoAtendentesVazio = String(variaveis.atendentes_transferencia_vazio ?? '').trim();
const textoAtendentesOnlineVazio = String(variaveis.atendentes_online_vazio ?? '').trim();

const abrirLista = (itens) => {
  if (itens.length === 1 && Array.isArray(itens[0])) return itens[0];
  return itens.flatMap((item) => {
    if (Array.isArray(item)) return item;
    return item?.content ?? item?.data ?? item?.items ?? item?.usuarios ?? [item];
  });
};

const disponiveis = abrirLista(disponiveisBrutos)
  .filter((item) => item && (item.usuarioId || item.id))
  .map((item) => ({
    atendente_id: String(item.usuarioId ?? item.id),
    nome: String(item.nome ?? ''),
    disponivel_agora: true
  }));

const idsDisponiveis = new Set(disponiveis.map((atendente) => atendente.atendente_id));
const lerBooleanoUsuario = (valor) => typeof valor === 'boolean'
  ? valor
  : ['true', '1', 'sim', 's', 'yes', 'on'].includes(String(valor ?? '').trim().toLowerCase());
// ATENDENTE aparece por nome. SUBGESTOR e candidato ao unico botao
// especial Outros, decidido pelo EV-03 apos consultar a disponibilidade.
const normalizarPapelAtendimento = (papel) => String(papel ?? '').trim().toUpperCase();
const participaDaListaDeTransferencia = (usuario) => {
  const papel = normalizarPapelAtendimento(usuario?.papel);
  // Michele e a unica subgestora permitida neste contrato. Outros nunca
  // deve encaminhar para outro subgestor por contingencia.
  return papel === 'ATENDENTE' || (papel === 'SUBGESTOR' && String(usuario?.id) === 'd1a021b3-6510-4783-88c4-be9813c6aff6');
};
const atendentesTransferencia = usuarios
  .filter((usuario) => usuario && usuario.ativo !== false && usuario.id)
  .filter(participaDaListaDeTransferencia)
  .filter((usuario) => lerBooleanoUsuario(usuario.disponivelParaIa ?? usuario.disponivel_para_ia))
  .map((usuario) => ({
    atendente_id: String(usuario.id),
    nome: String(usuario.nome ?? ''),
    papel: normalizarPapelAtendimento(usuario.papel),
    status: idsDisponiveis.has(String(usuario.id)) ? 'online' : 'offline',
    disponivel_agora: idsDisponiveis.has(String(usuario.id))
  }));

const formatarAtendente = (atendente) => {
  const nome = atendente.nome || 'Sem nome';
  const status = atendente.disponivel_agora ? 'online' : 'offline';
  return '- ' + nome + ' = ' + status + ' | id: ' + atendente.atendente_id;
};

const parametros = Array.isArray(configBruta.parametros) ? configBruta.parametros : [];
const normalizarConfig = (valor) => String(valor ?? '')
  .normalize('NFD')
  .replace(/[^a-z0-9]/gi, '')
  .toLowerCase();
const lerParametro = (...chaves) => {
  const chavesNormalizadas = chaves.map(normalizarConfig);
  const encontrado = parametros.find((parametro) => chavesNormalizadas.includes(normalizarConfig(parametro.chave)));
  return encontrado?.valor ?? encontrado?.value ?? '';
};
const normalizarBooleano = (valor) => ['true', '1', 'sim', 'yes', 'on'].includes(normalizarConfig(valor));
const transferenciaPorListaBruta =
  configBruta['transferencia.por_lista'] ??
  configBruta.transferencia_por_lista ??
  configBruta.transferencia?.por_lista ??
  lerParametro('transferencia.por_lista', 'transferencia_por_lista', 'transferencia por lista');
const transferenciaConfigBruta = configBruta.transferencia ??
  configBruta.modoTransferencia ??
  configBruta.modo_transferencia ??
  lerParametro('transferencia', 'modo_transferencia', 'modo de transferencia');
const transferenciaValor = typeof transferenciaConfigBruta === 'object' && transferenciaConfigBruta !== null
  ? (transferenciaConfigBruta.modo ?? transferenciaConfigBruta.valor ?? transferenciaConfigBruta.value ?? transferenciaConfigBruta.tipo ?? '')
  : transferenciaConfigBruta;
const usarListaAtendentes = normalizarBooleano(transferenciaPorListaBruta) ||
  ['lista', 'list', 'botoes', 'botoesatendentes', 'listaonline'].includes(normalizarConfig(transferenciaValor));
const automacao = {
  parametros: parametros
    .map((parametro) => ({
      chave: String(parametro.chave ?? ''),
      valor: String(parametro.valor ?? ''),
      tipo: String(parametro.tipo ?? ''),
      descricao: String(parametro.descricao ?? '')
    }))
    .filter((parametro) => parametro.chave && parametro.valor && !['transferencia', 'transferenciaporlista', 'modotransferencia', 'mododetransferencia'].includes(normalizarConfig(parametro.chave))),
  exige_template_fora_da_janela: Boolean(configBruta.exigeTemplateForaDaJanela)
};

// Formata a FAQ em texto simples para os prompts.
// A triagem recebe somente os itens cuja chave/nome contem "horario".
let respostasFaq = faqBruta.respostas ?? [];
if (typeof respostasFaq === 'string') {
  try { respostasFaq = JSON.parse(respostasFaq); } catch { respostasFaq = []; }
}
if (!Array.isArray(respostasFaq)) respostasFaq = [];
const formatarFaq = (itens) => itens.length
  ? itens.map((item) => {
    const nome = String(item?.nome ?? 'Sem chave').trim();
    const pergunta = String(item?.pergunta ?? '').trim();
    const resposta = String(item?.resposta ?? '').trim();
    return '- ' + nome + '\n  Pergunta: ' + pergunta + '\n  Resposta: ' + resposta;
  }).join('\n')
  : '';
const normalizar = (texto) => String(texto ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase();
const faqHorarioChave = normalizar(variaveis.faq_nome_busca_horario);
if (!faqHorarioChave) throw new Error('FAQ_CHAVE_HORARIO_NAO_CONFIGURADA');
const respostasHorario = respostasFaq.filter((item) => normalizar(item?.nome).includes(faqHorarioChave));
const faqInstitucionalTexto = formatarFaq(respostasFaq) || textoFaqInstitucionalVazia;
const faqHorarioTexto = formatarFaq(respostasHorario) || textoFaqHorarioVazio;
const obterPartesSP = (data) => {
  const partes = new Intl.DateTimeFormat('en-US', {
    timeZone: timezone,
    weekday: 'short',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23'
  }).formatToParts(data).reduce((acc, parte) => {
    acc[parte.type] = parte.value;
    return acc;
  }, {});

  return {
    diaSemana: { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 }[partes.weekday],
    minutos: Number(partes.hour) * 60 + Number(partes.minute)
  };
};

const extrairFaixasHorario = (textoHorario) => {
  const faixas = [];
  for (const parte of String(textoHorario ?? '').split(',')) {
    const texto = normalizar(parte);
    const horarios = [...String(parte).matchAll(/(\d{1,2})(?::|h)?(\d{2})?/g)]
      .map((match) => Number(match[1]) * 60 + Number(match[2] ?? 0));
    if (horarios.length < 2) continue;

    let dias = [];
    if (texto.includes('segunda') && texto.includes('sexta')) dias = [1, 2, 3, 4, 5];
    else if (texto.includes('sabado')) dias = [6];
    else if (texto.includes('domingo')) dias = [0];
    if (!dias.length) continue;

    for (const diaSemana of dias) {
      faixas.push({ diaSemana, inicio: horarios[0], fim: horarios[1] });
    }
  }
  return faixas;
};

const respostaListaAtendente = preparado.transferencia_lista_resposta ?? null;
const atendenteEscolhidoNaLista = respostaListaAtendente?.atendente_id
  ? atendentesTransferencia.find((atendente) => String(atendente.atendente_id) === String(respostaListaAtendente.atendente_id))
  : null;

const horarioFaqResposta = String(respostasHorario[0]?.resposta ?? '');
const faixasHorarioHumano = extrairFaixasHorario(horarioFaqResposta);
const horarioAtualSP = obterPartesSP(new Date(preparado.metadados?.recebido_em || Date.now()));
const dentroHorarioFaq = faixasHorarioHumano.length
  ? faixasHorarioHumano.some((faixa) => faixa.diaSemana === horarioAtualSP.diaSemana && horarioAtualSP.minutos >= faixa.inicio && horarioAtualSP.minutos <= faixa.fim)
  : null;

const dataHoraAtualSP = new Intl.DateTimeFormat('pt-BR', {
  timeZone: timezone,
  dateStyle: 'short',
  timeStyle: 'short'
}).format(new Date(preparado.metadados?.recebido_em || Date.now()));
const horarioVeioDoCrm = typeof preparado.horario?.dentro_horario_humano === 'boolean';
const dentroHorarioInformado = horarioVeioDoCrm
  ? preparado.horario.dentro_horario_humano
  : dentroHorarioFaq;
const horarioHumanoOrigem = horarioVeioDoCrm
  ? 'CRM'
  : (dentroHorarioFaq === null ? 'FAQ_NAO_RECONHECIDA' : 'FAQ');
const semAtendenteOnline = disponiveis.length === 0;
const modoForaAtendimentoHumano = semAtendenteOnline || dentroHorarioInformado === false;
const motivo = dentroHorarioInformado === false
  ? (horarioVeioDoCrm ? 'FORA_DO_HORARIO_INFORMADO_PELO_CRM' : 'FORA_DO_HORARIO_PELA_FAQ')
  : (semAtendenteOnline ? 'SEM_ATENDENTE_ONLINE' : 'ATENDIMENTO_HUMANO_POTENCIALMENTE_DISPONIVEL');

return [{ json: {
  ...preparado,
  automacao,
  transferencia_config: { usar_lista_atendentes: usarListaAtendentes },
  transferencia_lista_resposta: respostaListaAtendente ? {
    atendente_id: String(respostaListaAtendente.atendente_id ?? ''),
    titulo: String(respostaListaAtendente.titulo ?? ''),
    atendente_encontrado: Boolean(atendenteEscolhidoNaLista)
  } : null,
  faq_institucional_texto: faqInstitucionalTexto,
  faq_horario_texto: faqHorarioTexto,
  data_hora_atual_sp: dataHoraAtualSP,
  disponibilidade: {
    modo_fora_atendimento_humano: modoForaAtendimentoHumano,
    motivo,
    horario_humano_origem: horarioHumanoOrigem,
    quantidade_atendentes_online: disponiveis.length,
    atendentes_online: disponiveis,
    atendentes_transferiveis: atendentesTransferencia,
    atendentes_transferiveis_texto: atendentesTransferencia.length
      ? atendentesTransferencia.map(formatarAtendente).join('\n')
      : textoAtendentesVazio,
    atendentes_online_texto: disponiveis.length
      ? disponiveis.map(formatarAtendente).join('\n')
      : textoAtendentesOnlineVazio
  }
} }];

