// Prepara fatos objetivos e escolhe, por codigo, uma unica conduta de transferencia.
// A IA recebe a instrucao selecionada; ela nao precisa conciliar regras concorrentes.
const contexto = $('Definir modo de atendimento').first().json;
const memoria = $('Consultar memoria da sessao').first().json ?? {};
const variaveis = $('Variaveis de producao').first().json;
const timezone = String(variaveis.timezone ?? '').trim();
if (!timezone) throw new Error('TIMEZONE_NAO_CONFIGURADO');

const textoFaqHorarioVazio = String(variaveis.faq_horario_vazio ?? '').trim();
const horaInicioManha = Number(variaveis.saudacao_manha_inicio_hora);
const horaInicioTarde = Number(variaveis.saudacao_tarde_inicio_hora);
const horaInicioNoite = Number(variaveis.saudacao_noite_inicio_hora);
if (![horaInicioManha, horaInicioTarde, horaInicioNoite].every(Number.isFinite)) {
  throw new Error('HORARIOS_SAUDACAO_NAO_CONFIGURADOS');
}

const totalMemoria = Number(memoria.total_memoria ?? 0);
const foraDoHorarioHumano = contexto.disponibilidade?.modo_fora_atendimento_humano === true;
const bloquearTransferenciaGenericaForaHorarioComMemoria =
  totalMemoria > 0 && foraDoHorarioHumano;

// Cada caso tem uma instrucao completa e exclusiva. Isto evita que o agente
// leia uma regra de "primeira mensagem" e outra de "continuidade" ao mesmo tempo.
let modoPromptTransferencia;
let instrucaoOperacionalTransferencia;

if (totalMemoria === 0) {
  modoPromptTransferencia = 'PRIMEIRA_MENSAGEM_LISTA';
  instrucaoOperacionalTransferencia = [
    'MODO: PRIMEIRA MENSAGEM SEM MEMORIA.',
    'Se o cliente nao citar um atendente especifico e a mensagem nao for uma duvida institucional claramente identificada, chame transferir_atendimento agora com transferir_para_atendente_especifico=false e atendente_id vazio.',
    'Isso inclui saudacoes como "oi", mensagens curtas e mensagens ambiguas. Nao responda apenas com uma saudacao nem pergunte preferencia antes de chamar a tool.',
    'Se o cliente citar um nome com correspondencia unica em LISTA_DE_ATENDENTES, use transferencia especifica com o id exato.'
  ].join(' ');
} else if (foraDoHorarioHumano) {
  modoPromptTransferencia = 'CONTINUIDADE_FORA_HORARIO';
  instrucaoOperacionalTransferencia = [
    'MODO: CONTINUIDADE COM MEMORIA FORA DO HORARIO.',
    'E proibido chamar transferir_atendimento de forma generica e e proibido enviar ou pedir lista de atendentes.',
    'Informe brevemente que estamos fora do horario de atendimento e peca o nome do atendente que ja acompanhava o caso para repassar corretamente.',
    'Nao transforme uma saudacao, problema, pedido de orcamento, reclamacao ou pedido generico de retorno em transferencia automatica.',
    'A unica excecao e quando o cliente ja informou um nome com correspondencia unica em LISTA_DE_ATENDENTES: nesse caso, a transferencia especifica continua permitida.'
  ].join(' ');
} else {
  modoPromptTransferencia = 'TRIAGEM_LISTA_DIRETA';
  instrucaoOperacionalTransferencia = [
    'MODO: TRIAGEM COM LISTA DIRETA.',
    'O router ja encaminhou esta mensagem para triagem e transferencia, portanto ela nao e uma duvida institucional.',
    'Chame transferir_atendimento agora com transferir_para_atendente_especifico=false e atendente_id vazio para enviar a lista de atendentes.',
    'Isso tambem vale quando existe memoria anterior. Nao responda apenas com saudacao, nem investigue o assunto antes de chamar a tool.',
    'Se o cliente citar um nome com correspondencia unica em LISTA_DE_ATENDENTES, use transferencia especifica com o id exato.'
  ].join(' ');
}

const agora = new Date(contexto.metadados?.recebido_em || Date.now());
const horaSP = Number(new Intl.DateTimeFormat('pt-BR', {
  timeZone: timezone,
  hour: '2-digit',
  hour12: false
}).format(agora));
const saudacao = horaSP >= horaInicioManha && horaSP < horaInicioTarde
  ? String(variaveis.saudacao_manha_texto ?? '')
  : (horaSP >= horaInicioTarde && horaSP < horaInicioNoite
    ? String(variaveis.saudacao_tarde_texto ?? '')
    : String(variaveis.saudacao_noite_texto ?? ''));

return [{ json: {
  ...contexto,
  triagem: {
    primeira_mensagem: totalMemoria === 0,
    total_memoria_antes_da_ia: totalMemoria,
    saudacao_contextual: saudacao,
    data_hora_atual_sp: contexto.data_hora_atual_sp,
    faq_horario_atendimento_disponivel: Boolean(contexto.faq_horario_texto && String(contexto.faq_horario_texto) !== textoFaqHorarioVazio),
    atendimento_humano_indisponivel: Boolean(foraDoHorarioHumano),
    motivo_indisponibilidade: String(contexto.disponibilidade?.motivo ?? ''),
    decisao_transferencia_responsavel: 'IA',
    modo_prompt_transferencia: modoPromptTransferencia,
    instrucao_operacional_transferencia: instrucaoOperacionalTransferencia,
    bloquear_transferencia_generica_fora_horario_com_memoria: bloquearTransferenciaGenericaForaHorarioComMemoria,
    conduta_transferencia: bloquearTransferenciaGenericaForaHorarioComMemoria
      ? 'FORA_HORARIO_COM_HISTORICO_PEDIR_NOME_SEM_TRANSFERIR'
      : 'REGRA_PADRAO',
    resposta_lista_atendente: contexto.transferencia_lista_resposta ?? null
  }
} }];

