// Prepara a resposta final sem depender do agente quando a mensagem bater com comando_reset_memoria.
// Quando um ramo opcional nao executa, a leitura dele retorna null para nao interromper o fluxo.
const mensagemBase = $('Preparar mensagem recebida').first().json;
const variaveis = $('Variaveis de producao').first().json;
const comandoReset = String(variaveis.comando_reset_memoria ?? '').trim().toLowerCase();
if (!comandoReset) throw new Error('COMANDO_RESET_MEMORIA_NAO_CONFIGURADO');
const resetou = String(mensagemBase.mensagem_cliente ?? '').trim().toLowerCase() === comandoReset;
const contexto = resetou
  ? $('Busca atendimento id').first().json
  : $('Aplicar requisitos triagem inicial').first().json;

if (resetou) {
  return [{ json: {
    enviar_resposta: true,
    codigo: 'MEMORIA_RESETADA',
    texto: String(variaveis.texto_reset_memoria ?? ''),
    wa_id: String(mensagemBase.contato?.wa_id ?? contexto.contato?.wa_id ?? ''),
    phone_number_id: String(mensagemBase.metadados?.phone_number_id ?? contexto.metadados?.phone_number_id ?? ''),
    atendimento_id: String(contexto.crm?.atendimento_id ?? mensagemBase.metadados?.atendimento_id ?? ''),
    motivo: String(variaveis.motivo_reset_memoria ?? '')
  } }];
}

// Alguns nodes so existem em um dos ramos. O n8n lanca erro ao pedir main de um node sem execucao.
const obterSaidaOpcional = (nomeNode) => {
  try {
    const node = $(nomeNode);
    return node.isExecuted ? node.first().json : null;
  } catch {
    return null;
  }
};

const triagem = obterSaidaOpcional('Triagem da Estrutural');
const institucional = obterSaidaOpcional('Atendimento institucional');
const saida = triagem ?? institucional ?? {};
const textoBruto = String(saida.output ?? saida.text ?? '').trim();
// Nunca envia objetos internos do agente ao WhatsApp.
const pareceJsonInterno = /^\s*\{[\s\S]*\}\s*$/.test(textoBruto) && /"(?:resumo_transferencia|atendente_id|transferir_para_atendente_especifico)"/.test(textoBruto);
const texto = pareceJsonInterno ? '' : textoBruto;
const transferenciaExecutada = Boolean(saida.intermediateSteps?.some((step) => {
  const retorno = step.observation ?? step.returnValues ?? step.output ?? {};
  const textoRetorno = typeof retorno === 'string' ? retorno : JSON.stringify(retorno);
  return textoRetorno.includes('TRANSFERENCIA_REALIZADA') || textoRetorno.includes('CLIENTE_TRANSFERIDO') || textoRetorno.includes('LISTA_ATENDENTES_ENVIADA') || textoRetorno.includes('LISTA_ATENDENTES_INDISPONIVEIS_ENVIADA');
}));

const retornoTransferencia = obterSaidaOpcional('transferir_atendimento');
const transferenciaExecutadaPelaTool = Boolean(
  retornoTransferencia?.sucesso === true &&
  retornoTransferencia?.mensagem_cliente_enviada === true &&
  ['LISTA_ATENDENTES_ENVIADA', 'LISTA_ATENDENTES_INDISPONIVEIS_ENVIADA', 'AVISO_FORA_HORARIO_COM_HISTORICO_ENVIADO', 'TRANSFERENCIA_REALIZADA', 'CLIENTE_TRANSFERIDO'].includes(String(retornoTransferencia.codigo ?? ''))
);
if (transferenciaExecutada || transferenciaExecutadaPelaTool) {
  return [{ json: {
    enviar_resposta: false,
    codigo: 'ACAO_TRANSFERENCIA_PROCESSADA_SEM_RESPOSTA_EXTRA',
    texto: '',
    wa_id: String(contexto.contato?.wa_id ?? ''),
    phone_number_id: String(contexto.metadados?.phone_number_id ?? ''),
    atendimento_id: String(contexto.crm?.atendimento_id ?? ''),
    motivo: 'O EV-03 ja envia a confirmacao, aviso ou lista ao cliente.'
  } }];
}

return [{ json: {
  enviar_resposta: Boolean(texto),
  codigo: texto ? 'RESPOSTA_DA_IA_PRONTA' : 'SEM_RESPOSTA_DA_IA',
  texto,
  wa_id: String(contexto.contato?.wa_id ?? ''),
  phone_number_id: String(contexto.metadados?.phone_number_id ?? ''),
  atendimento_id: String(contexto.crm?.atendimento_id ?? ''),
  motivo: texto ? '' : 'Agente nao retornou texto para envio.'
} }];

// Confirma o envio pela Meta para o EV-00.
// Este retorno ser?f? trocado pelo resultado do CRM quando /responder estiver integrado ao webhook.
const meta = $('Enviar resposta pela Meta').first().json;
return [{ json: {
  codigo: 'RESPOSTA_ENVIADA',
  enviado: true,
  whatsapp_message_id: String(meta.messages?.[0]?.id ?? '')
} }];

