SELECT
  COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'nome', nome,
        'pergunta', pergunta,
        'resposta', resposta
      )
      ORDER BY id
    ),
    '[]'::jsonb
  ) AS respostas
FROM public.faq;

parameters.jsCode:
// Compacta os usuarios retornados pelo CRM em um unico item.
// Sem isso, os proximos nodes rodam uma vez para cada usuario e multiplicam a execucao.
const usuarios = $('Consultar equipe CRM').all().flatMap((item) => {
  const json = item.json ?? {};
  if (Array.isArray(json)) return json;
  return json.usuarios ?? json.content ?? json.data ?? json.items ?? [json];
});

const normalizarNome = (nome) => String(nome ?? '')
  .normalize('NFD')
  .replace(/[^a-z0-9]/gi, '')
  .toLowerCase();

// Filtro temporario hardcoded: remove atendentes de teste antes de montar o contexto da IA.
// Assim esses nomes nao chegam no prompt e nao podem ser escolhidos para transferencia.
const nomesBloqueados = new Set(['teste3', 'teste2', 'testeatendente']);

return [{
  json: {
    usuarios: usuarios
      .filter((usuario) => usuario && (usuario.id || usuario.usuarioId))
      .filter((usuario) => !nomesBloqueados.has(normalizarNome(usuario.nome)))
      .map((usuario) => ({
        id: String(usuario.id ?? usuario.usuarioId),
        nome: String(usuario.nome ?? ''),
        email: String(usuario.email ?? ''),
        papel: String(usuario.papel ?? ''),
        statusPresenca: String(usuario.statusPresenca ?? ''),
        ativo: usuario.ativo !== false,
        disponivelParaIa: typeof usuario.disponivelParaIa === 'boolean'
          ? usuario.disponivelParaIa
          : ['true', '1', 'sim', 's', 'yes', 'on'].includes(String(usuario.disponivelParaIa ?? usuario.disponivel_para_ia ?? '').trim().toLowerCase())
      }))
  }
}];

// Encerra o subworkflow sem enviar mensagem ao cliente.
// Isso evita que a IA responda conversas ja transferidas ou assumidas por humano.
const contexto = $('Busca atendimento id').first().json;
return [{ json: {
  codigo: 'ATENDIMENTO_NAO_ESTA_EM_IA',
  enviado: false,
  processado: false,
  motivo: 'Atendimento localizado no CRM, mas nao esta sob responsabilidade da IA.',
  atendimento_id: String(contexto.crm?.atendimento_id ?? ''),
  lead_id: String(contexto.crm?.lead_id ?? ''),
  status_atendimento: String(contexto.crm?.status_atendimento ?? ''),
  modo_atendimento: String(contexto.crm?.modo_atendimento ?? '')
} }];

// Encerra o EV-01 sem novo envio pela Meta.
// A mensagem de transferencia ja foi enviada e registrada dentro do EV-03.
const preparado = $('Preparar resposta para envio').first().json;
return [{ json: {
  codigo: String(preparado.codigo ?? 'TRANSFERENCIA_PROCESSADA'),
  enviado: true,
  processado: true,
  atendimento_id: String(preparado.atendimento_id ?? ''),
  motivo: String(preparado.motivo ?? '')
} }];

// Converte uma selecao interativa em transferencia antes de qualquer chamada da IA.
// Quando nao ha selecao, mantem o fallback para JSON interno eventualmente devolvido pela IA.
const contexto = $('Aplicar requisitos triagem inicial').first().json;
const atendentes = contexto.disponibilidade?.atendentes_transferiveis ?? [];
const selecaoLista = contexto.transferencia_lista_resposta ?? null;
const tituloLista = String(selecaoLista?.titulo ?? '').trim();
const atendenteIdLista = String(selecaoLista?.atendente_id ?? '').trim();
const atendenteDaListaExiste = atendentes.some((atendente) => String(atendente.atendente_id) === atendenteIdLista);
// Outros representa o atendente de contingencia configurado no EV-00 e pode nao constar na lista operacional.
const transferenciaDaLista = Boolean(atendenteIdLista && tituloLista && (tituloLista === 'Outros' || atendenteDaListaExiste));

let dados = null;
if (!transferenciaDaLista) {
  const triagem = $('Triagem da Estrutural').first().json;
  const textoBruto = String(triagem.output ?? triagem.text ?? '').trim();
  if (/^\s*\{[\s\S]*\}\s*$/.test(textoBruto)) {
    try { dados = JSON.parse(textoBruto); } catch { dados = null; }
  }
}

const transferirEspecificoIa = dados?.transferir_para_atendente_especifico === true;
const transferenciaGenerica = dados?.transferir_para_atendente_especifico === false;
const atendenteIdIa = String(dados?.atendente_id ?? '').trim();
const resumoIa = String(dados?.resumo_transferencia ?? '').trim();
const atendenteDaIaExiste = atendentes.some((atendente) => String(atendente.atendente_id) === atendenteIdIa);
const transferirEspecifico = transferenciaDaLista || transferirEspecificoIa;
const atendenteId = transferenciaDaLista ? atendenteIdLista : atendenteIdIa;
const resumo = transferenciaDaLista ? `Cliente selecionou ${tituloLista} na lista de atendentes.` : resumoIa;
const dadosMinimos = transferenciaDaLista || Boolean(resumo && (transferenciaGenerica || (transferirEspecificoIa && atendenteIdIa && atendenteDaIaExiste)));

return [{ json: {
  transferencia_declarada_valida: dadosMinimos,
  motivo_fallback_transferencia: transferenciaDaLista ? 'SELECAO_DA_LISTA_CONVERTIDA_EM_CHAMADA_EV03' : (dadosMinimos ? 'JSON_INTERNO_DA_IA_CONVERTIDO_EM_CHAMADA_EV03' : 'SEM_TRANSFERENCIA_DECLARADA_VALIDA'),
  atendimento_id: String(contexto.crm?.atendimento_id || contexto.metadados?.atendimento_id || ''),
  resumo_transferencia: resumo,
  transferir_para_atendente_especifico: transferirEspecifico,
  atendente_id: transferirEspecifico ? atendenteId : '',
  mensagem_id: String(contexto.metadados?.mensagem_id ?? ''),
  wa_id: String(contexto.contato?.wa_id ?? ''),
  phone_number_id: String(contexto.metadados?.phone_number_id ?? ''),
  atendentes_transferiveis_json: JSON.stringify(atendentes),
  lead_nome: String(contexto.contato?.nome ?? ''),
  fora_horario_humano: contexto.disponibilidade?.modo_fora_atendimento_humano === true,
  usar_lista_atendentes: contexto.transferencia_config?.usar_lista_atendentes === true
} }];

// Finaliza o EV-01 quando o fallback chamou o EV-03.
// O EV-03 ja enviou a mensagem sistematica de transferencia ao cliente.
const resultado = $('Executar transferencia declarada').first().json;
return [{ json: {
  codigo: 'TRANSFERENCIA_DECLARADA_PROCESSADA',
  enviado: true,
  processado: true,
  atendimento_id: String(resultado.atendimento_id ?? resultado.atendimentoId ?? ''),
  motivo: 'Fallback executou EV-03 porque a IA devolveu argumentos da tool como JSON.'
} }];

// Monta a chamada do EV-03 para reenviar a lista apos o cliente digitar #sair.
// Aqui nao chamamos IA: usamos a equipe ja consultada e o mesmo contrato de transferencia por lista.
const contexto = $('Busca atendimento id').first().json;
const mensagem = $('Preparar mensagem recebida').first().json;
const variaveis = $('Variaveis de producao').first().json;
const disponiveisBrutos = $('Consultar atendentes disponiveis').all().map((item) => item.json);
const usuarios = $('Compactar equipe CRM').first().json.usuarios ?? [];

const abrirLista = (itens) => {
  if (itens.length === 1 && Array.isArray(itens[0])) return itens[0];
  return itens.flatMap((item) => {
    if (Array.isArray(item)) return item;
    return item?.content ?? item?.data ?? item?.items ?? item?.usuarios ?? [item];
  });
};

const disponiveis = abrirLista(disponiveisBrutos)
  .filter((item) => item && (item.usuarioId || item.id))
  .map((item) => ({
    atendente_id: String(item.usuarioId ?? item.id),
    nome: String(item.nome ?? ''),
    disponivel_agora: true,
    status: 'online'
  }));

const idsDisponiveis = new Set(disponiveis.map((atendente) => atendente.atendente_id));
const lerBooleano = (valor) => typeof valor === 'boolean'
  ? valor
  : ['true', '1', 'sim', 's', 'yes', 'on'].includes(String(valor ?? '').trim().toLowerCase());

// Usa o mesmo contrato da rota normal: ATENDENTE aparece por nome e
// SUBGESTOR e candidato ao unico botao Outros no EV-03.
const normalizarPapelAtendimento = (papel) => String(papel ?? '').trim().toUpperCase();
const atendentesTransferiveis = usuarios
  .filter((usuario) => usuario && usuario.ativo !== false && usuario.id)
  .filter((usuario) => (normalizarPapelAtendimento(usuario.papel) === 'ATENDENTE' ||
    (normalizarPapelAtendimento(usuario.papel) === 'SUBGESTOR' && String(usuario.id) === 'd1a021b3-6510-4783-88c4-be9813c6aff6')))
  .filter((usuario) => lerBooleano(usuario.disponivelParaIa ?? usuario.disponivel_para_ia))
  .map((usuario) => ({
    atendente_id: String(usuario.id),
    nome: String(usuario.nome ?? ''),
    papel: normalizarPapelAtendimento(usuario.papel),
    status: idsDisponiveis.has(String(usuario.id)) ? 'online' : 'offline',
    disponivel_agora: idsDisponiveis.has(String(usuario.id))
  }));

return [{ json: {
  atendimento_id: String(contexto.crm?.atendimento_id ?? mensagem.metadados?.atendimento_id ?? ''),
  resumo_transferencia: 'Cliente digitou #sair e pediu para escolher outro atendente.',
  transferir_para_atendente_especifico: false,
  atendente_id: '',
  mensagem_id: String(mensagem.metadados?.mensagem_id ?? ''),
  wa_id: String(mensagem.contato?.wa_id ?? contexto.contato?.wa_id ?? ''),
  phone_number_id: String(mensagem.metadados?.phone_number_id ?? contexto.metadados?.phone_number_id ?? ''),
  atendentes_transferiveis_json: JSON.stringify(atendentesTransferiveis),
  lead_nome: String(contexto.contato?.nome ?? mensagem.contato?.nome ?? ''),
  fora_horario_humano: false,
  usar_lista_atendentes: true,
  motivo: String(variaveis.motivo_sair_atendimento ?? '')
} }];

// Retorna para o EV-00 sem enviar mensagem extra.
// A lista de atendentes ja foi enviada pelo EV-03, e o atendimento atual ja foi finalizado.
const limpeza = $('Limpar memoria e follow-ups do #sair').first().json;
const lead = $('Desvincular lead do #sair').first().json;
const lista = $('Reenviar lista apos #sair').first().json;
const finalizacao = $('Finalizar atendimento do #sair').first().json;
const contexto = $('Busca atendimento id').first().json;

return [{ json: {
  codigo: 'SAIDA_ATENDIMENTO_PROCESSADA',
  enviado: true,
  processado: true,
  atendimento_id: String(contexto.crm?.atendimento_id ?? ''),
  lead_id: String(contexto.crm?.lead_id ?? ''),
  status_atendimento: String(finalizacao.status ?? 'FINALIZADO'),
  lista_reenviada: lista.mensagem_cliente_enviada === true,
  codigo_lista: String(lista.codigo ?? ''),
  memorias_removidas: Number(limpeza.memorias_removidas ?? 0),
  followups_cancelados: Number(limpeza.followups_cancelados ?? 0),
  lead_desvinculado: Boolean(lead.id),
  motivo: 'Comando #sair processado sem resposta extra da IA.'
} }];
